use std::{fs, path::{Path, PathBuf}}; use super::file_entry::{FileEntry, kind_from_name, FileKind};
pub fn list_dir(path:&Path, show_hidden:bool)->anyhow::Result<Vec<FileEntry>>{ let mut v=Vec::new(); for e in fs::read_dir(path)?{ let e=e?; let name=e.file_name().to_string_lossy().to_string(); if !show_hidden && name.starts_with('.') {continue;} let md=e.metadata()?; let kind= if md.is_dir(){FileKind::Directory}else{kind_from_name(&name)}; v.push(FileEntry{name:name.clone(), path:e.path().display().to_string(), kind, size:md.len(), permissions:String::new(), modified:String::new(), owner:String::new(), group:String::new(), selected:false}); } v.sort_by_key(|e| (e.kind != FileKind::Directory, e.name.to_ascii_lowercase())); Ok(v) }
pub fn expand_tilde(p:&str)->PathBuf{ if let Some(rest)=p.strip_prefix("~/"){ dirs::home_dir().unwrap_or_default().join(rest) } else if p=="~" { dirs::home_dir().unwrap_or_default() } else { p.into() } }
